\section{Preliminaries}

\subsection{Cluster algebras}
Recall that $(\mathbb P, \oplus, \cdot)$ is a {\bf semifield } if $(\mathbb P,  \cdot)$ is an abelian multiplicative group endowed with a binary operation of auxiliary addition $\oplus$ which is commutative, associative, and distributive with respect to the multiplication $\cdot$ in $\mathbb P$.

Let $Trop(y_1,\cdots,y_m)$ be a free abelian group generated by $\{y_1,\cdots,y_m\}$. We define the addition $\oplus$ in $Trop(y_1,\cdots,y_m)$ by $\prod\limits_{i}y_i^{a_i}\oplus\prod\limits_{i}y_i^{b_i}=\prod\limits_{i}y_i^{min(a_i,b_i)}$, then $(Trop(y_1,\cdots,y_m), \oplus)$ is a semifield, which is called a {\bf tropical semifield}.


The multiplicative group of any semifield $\mathbb P$ is torsion-free \cite{FZ}, hence its group ring $\mathbb Z\mathbb P$ is a domain.
We take an ambient field $\mathcal F$  to be the field of rational functions in $n$ independent variables with coefficients in $\mathbb Z\mathbb P$.


An integer matrix $B_{n\times n}=(b_{ij})$ is  called  {\bf skew-symmetrizable} if there is a positive integer diagonal matrix $S$ such that $SB$ is skew-symmetric, where $S$ is said to be a {\bf skew-symmetrizer} of $B$.








\begin{Definition}
A {\bf  seed} in $\mathcal F$ is a triplet $({\bf x},{\bf y},B)$ such that

(i)  ${\bf x}=\{x_1,\cdots, x_n\}$ is a transcendence basis for $\mathcal F$ over Frac($\mathbb {ZP}$). ${\bf x}$ is called the  {\bf cluster} of  $({\bf x},{\bf y},B)$ and $x_1\cdots,x_n$  are called {\bf cluster variables}.

(ii) ${\bf y}=\{y_1,\cdots,y_n\}$ is a subset of  $\mathbb P$, where $y_1,\cdots,y_n$ are called {\bf coefficients}.

(iii) $B=(b_{ij})$ is a skew-symmetrizable matrix, called an {\bf exchange matrix}.
\end{Definition}




Let $({\bf x},{\bf y}, B)$ be a  seed in $\mathcal F$, one can associate {\em binomials} $F_1,\cdots,F_n$ defined by
\begin{eqnarray}
F_j=\frac{y_j}{1\oplus y_j}\prod\limits_{b_{ij}>0}x_i^{b_{ij}}+\frac{y_j}{1\oplus y_j}\prod\limits_{b_{ij}<0}x_i^{-b_{ij}}.\nonumber
\end{eqnarray}
$F_1,\cdots,F_n$ are called the {\bf exchange polynomials} of $({\bf x},{\bf y}, B)$. Clearly, $x_i\nmid F_j$ for any $i$ and $j$. Denote by ${\bf F}=\{F_1,\cdots,F_n\}$ the collection of  exchange polynomials of $({\bf x},{\bf y}, B)$.






